48	  fichaData: {
49	    id: number;
50	    nome: string;
51	    custo_calculado: number | null;
52	    rendimento_quantidade: number;
53	    rendimento_unidade: string;
54	    status: string;
55	  } | null;
56	  items: RawCmvItem[];
57	  custoReceita: number;
58	  custoEmbalagens: number;
