65	    valor_unitario: number | null;
66	    unidade: string | null;
67	    fornecedor: string | null;
68	    numero_nota: string | null;
69	    data_nota: string | null;
70	  }>;
71	  onClose: () => void;
72	  onRefetch: () => Promise<void>;
73	}
74	
75	// ---------------------------------------------------------------------------
76	// HELPERS
77	// ---------------------------------------------------------------------------
78	
79	// Robustly parse the node id segments.
80	// Formats: "cmv_<id>", "ficha_<id>", "item_<id>", "nf_nota_<id>"
81	function parseNodeId(nodeId: string): { kind: string; kindId: number | null; isNotaNode: boolean } {
82	  if (nodeId.startsWith('nf_nota_')) {
83	    const raw = nodeId.slice('nf_nota_'.length);
84	    const id = parseInt(raw, 10);
85	    return { kind: 'nf', kindId: Number.isNaN(id) ? null : id, isNotaNode: true };
86	  }
87	  const underscoreIdx = nodeId.indexOf('_');
88	  if (underscoreIdx === -1) return { kind: nodeId, kindId: null, isNotaNode: false };
89	  const kind = nodeId.slice(0, underscoreIdx);
90	  const rawId = nodeId.slice(underscoreIdx + 1);
91	  const id = parseInt(rawId, 10);
92	  return { kind, kindId: Number.isNaN(id) ? null : id, isNotaNode: false };
93	}
94	
95	// Unit conversion: convert qty from `fromUnit` to `toUnit`
96	// Supports: g↔kg, ml↔l, same unit (factor=1), unknown (factor=1)
97	function convertUnits(qty: number, fromUnit: string, toUnit: string): number {
98	  if (fromUnit === toUnit) return qty;
99	  const from = fromUnit.toLowerCase();
100	  const to = toUnit.toLowerCase();
101	  if (from === 'g' && to === 'kg') return qty * 0.001;
102	  if (from === 'kg' && to === 'g') return qty * 1000;
103	  if (from === 'ml' && to === 'l') return qty * 0.001;
104	  if (from === 'l' && to === 'ml') return qty * 1000;
105	  if (from === 'mg' && to === 'g') return qty * 0.001;
106	  if (from === 'g' && to === 'mg') return qty * 1000;
107	  // Incompatible units — return as-is (1:1 fallback)
108	  return qty;
109	}
110	
111	const UNIDADES_FICHA = ['g', 'kg', 'ml', 'l', 'un'] as const;
112	
113	// ---------------------------------------------------------------------------
114	// COMPONENT
115	// ---------------------------------------------------------------------------
116	
117	export function CmvDetailPanel({
118	  selectedNodeId,
119	  cmv,
120	  fichaData,
121	  items,
122	  custoReceita,
123	  custoEmbalagens,
124	  custoAvulsos,
125	  custoTotal,
126	  nfEmbalagemItems,
127	  onClose,
128	  onRefetch,
129	}: CmvDetailPanelProps) {
130	  // --- Shared state ---
131	  const [atrelarNFOpen, setAtrelarNFOpen] = useState(false);
132	  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
133	  const [isSaving, setIsSaving] = useState(false);
134	  const [isDeleting, setIsDeleting] = useState(false);
135	
136	  // --- Item (embalagem/avulso) fields ---
137	  const [editQty, setEditQty] = useState('');
138	  const [editUnit, setEditUnit] = useState('');
139	  const [editPreco, setEditPreco] = useState('');
140	  const [editObs, setEditObs] = useState('');
141	  const [editUnidadesPorEmbalagem, setEditUnidadesPorEmbalagem] = useState('');
142	
143	  // --- Ficha node edit fields (quantidade_ficha + unidade_ficha on cmv_fichas) ---
144	  const [editQuantidadeFicha, setEditQuantidadeFicha] = useState('');
145	  const [editUnidadeFicha, setEditUnidadeFicha] = useState<string>('g');
146	  const [isSavingFicha, setIsSavingFicha] = useState(false);
147	
148	  // --- CMV node edit fields (nome + rendimento on cmv_fichas) ---
149	  const [editNomeProduto, setEditNomeProduto] = useState('');
150	  const [editRendQty, setEditRendQty] = useState('');
151	  const [editRendUnit, setEditRendUnit] = useState('');
152	  const [isSavingCmv, setIsSavingCmv] = useState(false);
153	
154	  // ---------------------------------------------------------------------------
155	  // Formatters
156	  // ---------------------------------------------------------------------------
157	
158	  const formatMoney = (v: number | null | undefined) => {
159	    if (v == null) return 'R$ 0,00';
160	    return v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
161	  };
162	
163	  const formatDate = (d: string | null) => {
164	    if (!d) return '';
165	    return new Date(d).toLocaleDateString('pt-BR');
166	  };
167	
168	  // ---------------------------------------------------------------------------
169	  // Derived state
170	  // ---------------------------------------------------------------------------
171	
172	  const { kind, kindId, isNotaNode } = useMemo(
173	    () =>
174	      selectedNodeId
175	        ? parseNodeId(selectedNodeId)
176	        : { kind: '', kindId: null, isNotaNode: false },
177	    [selectedNodeId],
178	  );
179	
180	  const selectedItem = useMemo(() => {
181	    if (kind === 'item' && kindId !== null) return items.find((i) => i.id === kindId);
182	    return null;
183	  }, [kind, kindId, items]);
184	
185	  const selectedNFItem = useMemo(() => {
186	    if (selectedItem?.nf_item_id) {
187	      return nfEmbalagemItems.find((n) => n.id === selectedItem.nf_item_id);
188	    }
189	    return null;
190	  }, [selectedItem, nfEmbalagemItems]);
191	
192	  const selectedNotaNodesData = useMemo(() => {
193	    if (isNotaNode && kindId !== null) {
194	      return nfEmbalagemItems.find((n) => n.nota_id === kindId);
195	    }
196	    return null;
197	  }, [isNotaNode, kindId, nfEmbalagemItems]);
198	
199	  // Custo unitário da ficha base (R$/rendimento_unidade)
200	  const fichaUnitCost = useMemo(() => {
201	    if (!fichaData || fichaData.rendimento_quantidade <= 0) return 0;
202	    return (fichaData.custo_calculado ?? 0) / fichaData.rendimento_quantidade;
203	  }, [fichaData]);
204	
205	  // Preview em tempo real da contribuição estimada (antes de salvar)
206	  const fichaContribPreview = useMemo(() => {
207	    if (!fichaData) return null;
208	    const qty = parseFloat(editQuantidadeFicha);
209	    if (Number.isNaN(qty) || qty <= 0) return null;
210	    const convertedQty = convertUnits(qty, editUnidadeFicha, fichaData.rendimento_unidade);
211	    return fichaUnitCost * convertedQty;
212	  }, [editQuantidadeFicha, editUnidadeFicha, fichaUnitCost, fichaData]);
213	
214	  // ---------------------------------------------------------------------------
215	  // Sync fields when selection changes
216	  // ---------------------------------------------------------------------------
217	
218	  useEffect(() => {
219	    if (selectedItem) {
220	      setEditQty(selectedItem.quantidade?.toString() ?? '');
221	      setEditUnit(selectedItem.unidade ?? '');
222	      setEditPreco(selectedItem.preco_unitario_esboco?.toString() ?? '');
223	      setEditObs(selectedItem.observacao ?? '');
224	      setEditUnidadesPorEmbalagem(selectedItem.unidades_por_embalagem?.toString() ?? '');
225	    }
226	  }, [selectedItem]);
227	
228	  useEffect(() => {
229	    if (kind === 'ficha' && cmv) {
230	      setEditQuantidadeFicha(cmv.quantidade_ficha?.toString() ?? '');
231	      setEditUnidadeFicha(cmv.unidade_ficha ?? 'g');
232	    }
233	  }, [kind, cmv]);
234	
235	  useEffect(() => {
236	    if (kind === 'cmv' && cmv) {
237	      setEditNomeProduto(cmv.nome ?? '');
238	      setEditRendQty(cmv.rendimento_quantidade?.toString() ?? '');
239	      setEditRendUnit(cmv.rendimento_unidade ?? 'un');
240	    }
241	  }, [kind, cmv]);
242	
243	  // ---------------------------------------------------------------------------
244	  // Handlers — items
245	  // ---------------------------------------------------------------------------
246	
247	  const handleSaveItem = async () => {
248	    if (!selectedItem) return;
249	    setIsSaving(true);
250	
251	    const updates: Record<string, unknown> = {
252	      quantidade: parseFloat(editQty) || 0,
253	      unidade: editUnit,
254	      observacao: editObs,
255	      unidades_por_embalagem: parseFloat(editUnidadesPorEmbalagem) || 1,
256	    };
257	
258	    if (
259	      selectedItem.tipo === 'outro' ||
260	      (selectedItem.tipo === 'embalagem' && !selectedItem.nf_item_id)
261	    ) {
262	      updates.preco_unitario_esboco = parseFloat(editPreco) || 0;
263	    }
264	
265	    const { error } = await supabase.from('cmv_itens').update(updates).eq('id', selectedItem.id);
266	    setIsSaving(false);
267	
268	    if (error) {
269	      toast.error('Erro ao salvar: ' + error.message);
270	    } else {
271	      toast.success('Item atualizado');
272	      onRefetch();
273	    }
274	  };
275	
276	  const handleDeleteItem = async () => {
277	    if (!selectedItem) return;
278	    setIsDeleting(true);
279	    const { error } = await supabase.from('cmv_itens').delete().eq('id', selectedItem.id);
280	    setIsDeleting(false);
281	    setDeleteDialogOpen(false);
282	
283	    if (error) {
284	      toast.error('Erro ao excluir: ' + error.message);
285	    } else {
286	      toast.success('Item excluído');
287	      onClose();
288	      onRefetch();
289	    }
290	  };
291	
292	  const handleDesatrelarNF = async () => {
293	    if (!selectedItem) return;
294	    setIsSaving(true);
295	    const { error } = await supabase
296	      .from('cmv_itens')
297	      .update({ nf_item_id: null } as Record<string, unknown>)
298	      .eq('id', selectedItem.id);
299	    setIsSaving(false);
300	    if (error) {
301	      toast.error('Erro ao desatrelar: ' + error.message);
302	    } else {
303	      toast.success('NF desatrelada');
304	      onRefetch();
305	    }
306	  };
307	
308	  // ---------------------------------------------------------------------------
309	  // Handlers — ficha node
310	  // ---------------------------------------------------------------------------
311	
312	  const handleSaveFicha = async () => {
313	    if (!cmv) return;
314	    setIsSavingFicha(true);
315	    const { error } = await supabase
316	      .from('cmv_fichas')
317	      .update({
318	        quantidade_ficha: parseFloat(editQuantidadeFicha) || null,
319	        unidade_ficha: editUnidadeFicha || null,
320	      } as Record<string, unknown>)
321	      .eq('id', cmv.id);
322	    setIsSavingFicha(false);
323	    if (error) {
324	      toast.error('Erro ao salvar: ' + error.message);
325	    } else {
326	      toast.success('Quantidade da receita atualizada');
327	      onRefetch();
328	    }
329	  };
330	
331	  // ---------------------------------------------------------------------------
332	  // Handlers — CMV root node
333	  // ---------------------------------------------------------------------------
334	
335	  const handleSaveCmv = async () => {
336	    if (!cmv) return;
337	    setIsSavingCmv(true);
338	    const { error } = await supabase
339	      .from('cmv_fichas')
340	      .update({
341	        nome: editNomeProduto || cmv.nome,
342	        rendimento_quantidade: parseFloat(editRendQty) || null,
343	        rendimento_unidade: editRendUnit || null,
344	      } as Record<string, unknown>)
345	      .eq('id', cmv.id);
346	    setIsSavingCmv(false);
347	    if (error) {
348	      toast.error('Erro ao salvar: ' + error.message);
349	    } else {
350	      toast.success('Produto final atualizado');
351	      onRefetch();
352	    }
353	  };
354	
355	  // ---------------------------------------------------------------------------
356	  // Guard
357	  // ---------------------------------------------------------------------------
358	
359	  if (!selectedNodeId) return null;
360	
361	  // ---------------------------------------------------------------------------
362	  // Render
363	  // ---------------------------------------------------------------------------
364	
365	  return (
366	    <>
367	      <aside className="absolute top-14 right-0 bottom-0 w-full sm:w-[420px] z-20 bg-white/95 dark:bg-[#1A1A1A]/95 backdrop-blur-xl border-l border-[#57715B]/10 shadow-2xl overflow-y-auto overflow-x-hidden animate-in slide-in-from-right duration-300 flex flex-col">
368	        {/* ── HEADER ── */}
369	        <header className="sticky top-0 bg-white/95 dark:bg-[#1A1A1A]/95 border-b border-[#57715B]/10 p-4 flex items-center justify-between z-10 shrink-0">
370	          <div className="flex items-center gap-2">
371	            {kind === 'cmv' && <Calculator className="text-[#57715B]" size={20} />}
372	            {kind === 'ficha' && <ChefHat className="text-amber-500" size={20} />}
373	            {kind === 'item' && selectedItem?.tipo === 'embalagem' && (
374	              <Package className="text-blue-500" size={20} />
375	            )}
376	            {kind === 'item' && selectedItem?.tipo === 'outro' && (
377	              <DollarSign className="text-orange-500" size={20} />
378	            )}
379	            {isNotaNode && <Receipt className="text-cyan-500" size={20} />}
380	            <span className="font-semibold text-sm">
381	              {kind === 'cmv' && 'Produto Final'}
382	              {kind === 'ficha' && 'Ficha Base'}
383	              {kind === 'item' && selectedItem?.tipo === 'embalagem' && 'Detalhes da Embalagem'}
384	              {kind === 'item' && selectedItem?.tipo === 'outro' && 'Detalhes do Custo Avulso'}
385	              {isNotaNode && 'Detalhes da Nota Fiscal'}
386	            </span>
387	          </div>
388	          <Button
389	            variant="ghost"
390	            size="icon"
391	            aria-label="Fechar painel"
392	            className="h-10 w-10 hover:bg-[#57715B]/10 active:bg-[#57715B]/10"
393	            onClick={onClose}
394	          >
395	            <X size={18} className="text-muted-foreground" />
396	          </Button>
397	        </header>
398	
399	        <div className="p-5 flex-1 overflow-y-auto space-y-6">
400	
401	          {/* ══════════════════════════════════════════
402	              NODE CMV — Produto Final
403	          ══════════════════════════════════════════ */}
404	          {kind === 'cmv' && cmv && (
405	            <div className="space-y-5">
406	              {/* Editor de identidade do produto final */}
407	              <div>
408	                <p className="text-[10px] uppercase tracking-widest text-muted-foreground mb-3 font-semibold">
409	                  Identidade do Produto Final
410	                </p>
411	                <div className="space-y-3">
412	                  <div className="space-y-1">
413	                    <Label className="text-xs">Nome do Produto Final</Label>
414	                    <Input
415	                      value={editNomeProduto}
416	                      onChange={(e) => setEditNomeProduto(e.target.value)}
417	                      placeholder="Ex.: Canjica 200ml no pote"
418	                      className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
419	                    />
420	                  </div>
421	                  <div className="flex gap-2">
422	                    <div className="flex-1 space-y-1">
423	                      <Label className="text-xs">Rendimento Final (Qtd)</Label>
424	                      <Input
425	                        type="number"
426	                        value={editRendQty}
427	                        onChange={(e) => setEditRendQty(e.target.value)}
428	                        placeholder="Ex.: 200"
429	                        className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
430	                      />
431	                    </div>
432	                    <div className="w-28 space-y-1">
433	                      <Label className="text-xs">Unidade</Label>
434	                      <Input
435	                        value={editRendUnit}
436	                        onChange={(e) => setEditRendUnit(e.target.value)}
437	                        placeholder="ml / un / g"
438	                        className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
439	                      />
440	                    </div>
441	                  </div>
442	                </div>
443	                <Button
444	                  className="mt-3 w-full bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl"
445	                  onClick={handleSaveCmv}
446	                  disabled={isSavingCmv}
447	                >
448	                  {isSavingCmv ? (
449	                    <Loader2 size={14} className="animate-spin mr-2" />
450	                  ) : (
451	                    <Save size={14} className="mr-2" />
452	                  )}
453	                  Salvar Produto Final
454	                </Button>
455	              </div>
456	
457	              {/* Breakdown de custo */}
458	              <div>
459	                <p className="text-[10px] uppercase tracking-widest text-muted-foreground mb-3 font-semibold">
460	                  Breakdown do Custo
461	                </p>
462	                <div className="space-y-2">
463	                  <div className="flex items-center justify-between p-3 bg-amber-50 dark:bg-amber-900/10 rounded-xl border border-amber-200/30">
464	                    <span className="flex items-center gap-1.5 text-xs text-amber-700 dark:text-amber-400">
465	                      <ChefHat size={12} /> Receita
466	                    </span>
467	                    <span className="font-bold tabular-nums text-sm text-amber-700 dark:text-amber-400">
468	                      {formatMoney(custoReceita)}
469	                    </span>
470	                  </div>
471	                  <div className="flex items-center justify-between p-3 bg-blue-50 dark:bg-blue-900/10 rounded-xl border border-blue-200/30">
472	                    <span className="flex items-center gap-1.5 text-xs text-blue-700 dark:text-blue-400">
473	                      <Package size={12} /> Embalagens
474	                    </span>
475	                    <span className="font-bold tabular-nums text-sm text-blue-700 dark:text-blue-400">
476	                      {formatMoney(custoEmbalagens)}
477	                    </span>
478	                  </div>
479	                  <div className="flex items-center justify-between p-3 bg-orange-50 dark:bg-orange-900/10 rounded-xl border border-orange-200/30">
480	                    <span className="flex items-center gap-1.5 text-xs text-orange-700 dark:text-orange-400">
481	                      <DollarSign size={12} /> Avulsos
482	                    </span>
483	                    <span className="font-bold tabular-nums text-sm text-orange-700 dark:text-orange-400">
484	                      {formatMoney(custoAvulsos)}
485	                    </span>
486	                  </div>
487	                  <div className="flex items-center justify-between p-4 bg-[#57715B]/10 rounded-xl border border-[#57715B]/20 mt-1">
488	                    <span className="flex items-center gap-1.5 text-sm font-bold text-[#57715B] uppercase tracking-wide">
489	                      <Calculator size={14} /> Total
490	                    </span>
491	                    <span className="font-black tabular-nums text-xl text-[#57715B]">
492	                      {formatMoney(custoTotal)}
493	                    </span>
494	                  </div>
495	                  {cmv.rendimento_quantidade != null && cmv.rendimento_quantidade > 0 && (
496	                    <div className="text-[10px] text-right text-muted-foreground pt-1">
497	                      = {formatMoney(custoTotal / cmv.rendimento_quantidade)} /{' '}
498	                      {cmv.rendimento_unidade ?? 'un'}
499	                    </div>
500	                  )}
501	                </div>
502	              </div>
503	            </div>
504	          )}
505	
506	          {/* ══════════════════════════════════════════
507	              NODE FICHA BASE
508	          ══════════════════════════════════════════ */}
509	          {kind === 'ficha' && fichaData && (
510	            <div className="space-y-5">
511	              <div>
512	                <h2 className="text-xl font-bold text-[#2D362E] dark:text-[#E6DCCF] mb-1">
513	                  {fichaData.nome}
514	                </h2>
515	                <div className="flex items-center gap-2 flex-wrap">
516	                  <span className="text-amber-600 bg-amber-50 dark:bg-amber-900/20 px-2.5 py-1 rounded-full text-xs font-bold uppercase tracking-wider">
517	                    Rende: {fichaData.rendimento_quantidade} {fichaData.rendimento_unidade}
518	                  </span>
519	                  <span className="text-slate-600 bg-slate-100 dark:bg-slate-800 px-2.5 py-1 rounded-full text-xs font-bold uppercase tracking-wider">
520	                    {fichaData.status}
521	                  </span>
522	                </div>
523	              </div>
524	
525	              {/* Custo unitário da receita */}
526	              <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-4 border border-[#57715B]/10">
527	                <div className="text-xs uppercase tracking-wider text-muted-foreground font-semibold mb-1">
528	                  Custo Total da Ficha
529	                </div>
530	                <div className="text-3xl font-black tabular-nums text-[#2D362E] dark:text-[#E6DCCF]">
531	                  {formatMoney(fichaData.custo_calculado)}
532	                </div>
533	                {fichaData.rendimento_quantidade > 0 && (
534	                  <div className="text-emerald-600 font-bold text-lg tabular-nums mt-4 pt-4 border-t border-[#57715B]/10">
535	                    {formatMoney(fichaUnitCost)} / {fichaData.rendimento_unidade}
536	                  </div>
537	                )}
538	                {cmv?.quantidade_ficha != null && cmv.unidade_ficha && (
539	                  <div className="text-xs text-muted-foreground mt-2">
