    custo_calculado: number | null;
    rendimento_quantidade: number | null;
    rendimento_unidade: string | null;
    quantidade_ficha: number | null;
    unidade_ficha: string | null;
  } | null;
  fichaData: {
    id: number;
    nome: string;
    custo_calculado: number | null;
    rendimento_quantidade: number;
    rendimento_unidade: string;
    status: string;
  } | null;
  items: RawCmvItem[];
  custoReceita: number;
  custoEmbalagens: number;
  custoAvulsos: number;
  custoTotal: number;
  nfEmbalagemItems: Array<{
    id: number;
    nota_id: number;
    nome_produto: string | null;
    valor_unitario: number | null;
    unidade: string | null;
    fornecedor: string | null;
    numero_nota: string | null;
    data_nota: string | null;
  }>;
  onClose: () => void;
  onRefetch: () => Promise<void>;
}

function parseNodeId(nodeId: string): { kind: string; kindId: number | null; isNotaNode: boolean } {
  if (nodeId.startsWith('nf_nota_')) {
    const raw = nodeId.slice('nf_nota_'.length);
    const id = parseInt(raw, 10);
    return { kind: 'nf', kindId: Number.isNaN(id) ? null : id, isNotaNode: true };
  }
  const underscoreIdx = nodeId.indexOf('_');
  if (underscoreIdx === -1) return { kind: nodeId, kindId: null, isNotaNode: false };
  const kind = nodeId.slice(0, underscoreIdx);
  const rawId = nodeId.slice(underscoreIdx + 1);
  const id = parseInt(rawId, 10);
  return { kind, kindId: Number.isNaN(id) ? null : id, isNotaNode: false };
}

function convertUnits(qty: number, fromUnit: string, toUnit: string): number {
  if (fromUnit === toUnit) return qty;
  const from = fromUnit.toLowerCase();
  const to = toUnit.toLowerCase();
  if (from === 'g' && to === 'kg') return qty * 0.001;
  if (from === 'kg' && to === 'g') return qty * 1000;
  if (from === 'ml' && to === 'l') return qty * 0.001;
  if (from === 'l' && to === 'ml') return qty * 1000;
  if (from === 'mg' && to === 'g') return qty * 0.001;
  if (from === 'g' && to === 'mg') return qty * 1000;
  return qty;
}

const UNIDADES_FICHA = ['g', 'kg', 'ml', 'l', 'un'] as const;

