import { useState, useEffect, useMemo } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';
import {
  X, Package, DollarSign, ChefHat, Calculator, Receipt, Loader2, Save, Trash2, Calendar,
} from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from '@/shared/ui/alert-dialog';
import { CmvAtrelarNFDialog } from './CmvAtrelarNFDialog';
import type { RawCmvItem } from '@/features/financeiro/model/useCmvGraph';

interface CmvDetailPanelProps {
  selectedNodeId: string | null;
  cmv: {
    id: number; nome: string; status: string; custo_calculado: number | null;
    rendimento_quantidade: number | null; rendimento_unidade: string | null;
    quantidade_ficha: number | null; unidade_ficha: string | null;
  } | null;
  fichaData: {
    id: number; nome: string; custo_calculado: number | null;
    rendimento_quantidade: number; rendimento_unidade: string; status: string;
  } | null;
  items: RawCmvItem[];
  custoReceita: number; custoEmbalagens: number; custoAvulsos: number; custoTotal: number;
  nfEmbalagemItems: Array<{
    id: number; nota_id: number; nome_produto: string | null; valor_unitario: number | null;
    unidade: string | null; fornecedor: string | null; numero_nota: string | null; data_nota: string | null;
  }>;
  onClose: () => void;
  onRefetch: () => Promise<void>;
}

function parseNodeId(nodeId: string): { kind: string; kindId: number | null; isNotaNode: boolean } {
  if (nodeId.startsWith('nf_nota_')) {
    const raw = nodeId.slice('nf_nota_'.length);
    const id = parseInt(raw, 10);
    return { kind: 'nf', kindId: Number.isNaN(id) ? null : id, isNotaNode: true };
  }
  const underscoreIdx = nodeId.indexOf('_');
  if (underscoreIdx === -1) return { kind: nodeId, kindId: null, isNotaNode: false };
  const kind = nodeId.slice(0, underscoreIdx);
  const rawId = nodeId.slice(underscoreIdx + 1);
  const id = parseInt(rawId, 10);
  return { kind, kindId: Number.isNaN(id) ? null : id, isNotaNode: false };
}

function convertUnits(qty: number, fromUnit: string, toUnit: string): number {
  if (fromUnit === toUnit) return qty;
  const from = fromUnit.toLowerCase(); const to = toUnit.toLowerCase();
  if (from === 'g' && to === 'kg') return qty * 0.001;
  if (from === 'kg' && to === 'g') return qty * 1000;
  if (from === 'ml' && to === 'l') return qty * 0.001;
  if (from === 'l' && to === 'ml') return qty * 1000;
  if (from === 'mg' && to === 'g') return qty * 0.001;
  if (from === 'g' && to === 'mg') return qty * 1000;
  return qty;
}

const UNIDADES_FICHA = ['g', 'kg', 'ml', 'l', 'un'] as const;

export function CmvDetailPanel({ selectedNodeId, cmv, fichaData, items, custoReceita,
  custoEmbalagens, custoAvulsos, custoTotal, nfEmbalagemItems, onClose, onRefetch,
}: CmvDetailPanelProps) {
  const [atrelarNFOpen, setAtrelarNFOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [editQty, setEditQty] = useState('');
  const [editUnit, setEditUnit] = useState('');
  const [editPreco, setEditPreco] = useState('');
  const [editObs, setEditObs] = useState('');
  const [editUnidadesPorEmbalagem, setEditUnidadesPorEmbalagem] = useState('');
  const [editQuantidadeFicha, setEditQuantidadeFicha] = useState('');
  const [editUnidadeFicha, setEditUnidadeFicha] = useState<string>('g');
  const [isSavingFicha, setIsSavingFicha] = useState(false);
  const [editNomeProduto, setEditNomeProduto] = useState('');
  const [editRendQty, setEditRendQty] = useState('');
  const [editRendUnit, setEditRendUnit] = useState('');
  const [isSavingCmv, setIsSavingCmv] = useState(false);

  const formatMoney = (v: number | null | undefined) => {
    if (v == null) return 'R$ 0,00';
    return v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  };
  const formatDate = (d: string | null) => {
    if (!d) return '';
    return new Date(d).toLocaleDateString('pt-BR');
  };

  const { kind, kindId, isNotaNode } = useMemo(
    () => selectedNodeId ? parseNodeId(selectedNodeId) : { kind: '', kindId: null, isNotaNode: false },
    [selectedNodeId],
  );

  const selectedItem = useMemo(() => {
    if (kind === 'item' && kindId !== null) return items.find((i) => i.id === kindId);
    return null;
  }, [kind, kindId, items]);

  const selectedNFItem = useMemo(() => {
    if (selectedItem?.nf_item_id) return nfEmbalagemItems.find((n) => n.id === selectedItem.nf_item_id);
    return null;
  }, [selectedItem, nfEmbalagemItems]);

  const selectedNotaNodesData = useMemo(() => {
    if (isNotaNode && kindId !== null) return nfEmbalagemItems.find((n) => n.nota_id === kindId);
    return null;
  }, [isNotaNode, kindId, nfEmbalagemItems]);

  const fichaUnitCost = useMemo(() => {
    if (!fichaData || fichaData.rendimento_quantidade <= 0) return 0;
    return (fichaData.custo_calculado ?? 0) / fichaData.rendimento_quantidade;
  }, [fichaData]);

  const fichaContribPreview = useMemo(() => {
    if (!fichaData) return null;
    const qty = parseFloat(editQuantidadeFicha);
    if (Number.isNaN(qty) || qty <= 0) return null;
    const convertedQty = convertUnits(qty, editUnidadeFicha, fichaData.rendimento_unidade);
    return fichaUnitCost * convertedQty;
  }, [editQuantidadeFicha, editUnidadeFicha, fichaUnitCost, fichaData]);

  useEffect(() => {
    if (selectedItem) {
      setEditQty(selectedItem.quantidade?.toString() ?? '');
      setEditUnit(selectedItem.unidade ?? '');
      setEditPreco(selectedItem.preco_unitario_esboco?.toString() ?? '');
      setEditObs(selectedItem.observacao ?? '');
      setEditUnidadesPorEmbalagem(selectedItem.unidades_por_embalagem?.toString() ?? '');
    }
  }, [selectedItem]);

  useEffect(() => {
    if (kind === 'ficha' && cmv) {
      setEditQuantidadeFicha(cmv.quantidade_ficha?.toString() ?? '');
      setEditUnidadeFicha(cmv.unidade_ficha ?? 'g');
    }
  }, [kind, cmv]);

  useEffect(() => {
    if (kind === 'cmv' && cmv) {
      setEditNomeProduto(cmv.nome ?? '');
      setEditRendQty(cmv.rendimento_quantidade?.toString() ?? '');
      setEditRendUnit(cmv.rendimento_unidade ?? 'un');
    }
  }, [kind, cmv]);

  const handleSaveItem = async () => {
    if (!selectedItem) return;
    setIsSaving(true);
    const updates: Record<string, unknown> = {
      quantidade: parseFloat(editQty) || 0, unidade: editUnit,
      observacao: editObs, unidades_por_embalagem: parseFloat(editUnidadesPorEmbalagem) || 1,
    };
    if (selectedItem.tipo === 'outro' || (selectedItem.tipo === 'embalagem' && !selectedItem.nf_item_id)) {
      updates.preco_unitario_esboco = parseFloat(editPreco) || 0;
    }
    const { error } = await supabase.from('cmv_itens').update(updates).eq('id', selectedItem.id);
    setIsSaving(false);
    if (error) { toast.error('Erro ao salvar: ' + error.message); } else { toast.success('Item atualizado'); onRefetch(); }
  };

  const handleDeleteItem = async () => {
    if (!selectedItem) return;
    setIsDeleting(true);
    const { error } = await supabase.from('cmv_itens').delete().eq('id', selectedItem.id);
    setIsDeleting(false); setDeleteDialogOpen(false);
    if (error) { toast.error('Erro ao excluir: ' + error.message); } else { toast.success('Item excluído'); onClose(); onRefetch(); }
  };

  const handleDesatrelarNF = async () => {
    if (!selectedItem) return;
    setIsSaving(true);
    const { error } = await supabase.from('cmv_itens').update({ nf_item_id: null } as Record<string, unknown>).eq('id', selectedItem.id);
    setIsSaving(false);
    if (error) { toast.error('Erro ao desatrelar: ' + error.message); } else { toast.success('NF desatrelada'); onRefetch(); }
  };

  const handleSaveFicha = async () => {
    if (!cmv) return;
    setIsSavingFicha(true);
    const { error } = await supabase.from('cmv_fichas').update({
      quantidade_ficha: parseFloat(editQuantidadeFicha) || null,
      unidade_ficha: editUnidadeFicha || null,
    } as Record<string, unknown>).eq('id', cmv.id);
    setIsSavingFicha(false);
    if (error) { toast.error('Erro ao salvar: ' + error.message); } else { toast.success('Quantidade da receita atualizada'); onRefetch(); }
  };

  const handleSaveCmv = async () => {
    if (!cmv) return;
    setIsSavingCmv(true);
