// Unit conversion: convert qty from `fromUnit` to `toUnit`
// Supports: g↔kg, ml↔l, same unit (factor=1), unknown (factor=1)
function convertUnits(qty: number, fromUnit: string, toUnit: string): number {
  if (fromUnit === toUnit) return qty;
  const from = fromUnit.toLowerCase();
  const to = toUnit.toLowerCase();
  if (from === 'g' && to === 'kg') return qty * 0.001;
  if (from === 'kg' && to === 'g') return qty * 1000;
  if (from === 'ml' && to === 'l') return qty * 0.001;
  if (from === 'l' && to === 'ml') return qty * 1000;
  if (from === 'mg' && to === 'g') return qty * 0.001;
  if (from === 'g' && to === 'mg') return qty * 1000;
  // Incompatible units — return as-is (1:1 fallback)
  return qty;
}

